const src = $('Full Crawler1').item.json;
let parsed = { pain_points: [], likely_competitor_tools: '', competitor_gap: '', research_confidence: 'low' };
let research_ok = false, research_error = '';
try {
  let raw = $json.output;
  if (typeof raw !== 'string') raw = JSON.stringify(raw || {});
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  raw = (m ? m[0] : raw).replace(/,\s*([}\]])/g, '$1');
  const p = JSON.parse(raw);
  parsed = {
    pain_points: Array.isArray(p.pain_points) ? p.pain_points.filter(x => typeof x === 'string' && x.trim()).slice(0, 3) : [],
    likely_competitor_tools: (p.likely_competitor_tools || '').toString(),
    competitor_gap: (p.competitor_gap || '').toString(),
    research_confidence: p.research_confidence === 'high' ? 'high' : 'low'
  };
  research_ok = parsed.pain_points.length > 0;
  if (!research_ok) research_error = 'no pain points returned';
} catch (e) {
  research_error = 'parse_error: ' + e.message;
  console.warn(`[PARSE FAIL] research company=${src.company} error=${e.message}`);
}
return { json: { ...src, ...parsed, research_ok, research_error } };

const src = $('Match Knowledge Rows').item.json;
let parsed = { pain_point_used: '', competitor_angle: '', solution_description: '', cited_sources: '', grounded: false };
try {
  let raw = $json.output;
  if (typeof raw !== 'string') raw = JSON.stringify(raw || {});
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  raw = (m ? m[0] : raw).replace(/,\s*([}\]])/g, '$1');
  const p = JSON.parse(raw);
  const cited = Array.isArray(p.cited_sources) ? p.cited_sources : (p.cited_sources || '').toString().split(',');
  // keep only citations that really are matched Google Sheet titles
  const titles = (src.knowledge_sources || []);
  const validCited = cited.map(s => s.trim()).filter(s => titles.some(t => t.toLowerCase() === s.toLowerCase()));
  const hasSolution = !!(p.solution_description || '').toString().trim();
  const ok = p.grounded === true && hasSolution && validCited.length > 0 && src.knowledge_matches_found > 0;
  parsed = {
    pain_point_used: (p.pain_point_used || '').toString(),
    competitor_angle: (p.competitor_angle || '').toString(),
    solution_description: ok ? p.solution_description.toString() : '',
    cited_sources: ok ? validCited.map(t => 'Knowledge Base - ' + t).join(', ') : '',
    grounded: ok
  };
} catch (e) {
  console.warn(`[PARSE FAIL] grounded pitch company=${src.company} error=${e.message}`);
}
return { json: { ...src, ...parsed } };

console.warn(`[NO KNOWLEDGE MATCH] company=${$json.company} - no Google Sheet row reached the minimum score`);
return { json: { ...$json, knowledge_context: '', knowledge_sources: [], knowledge_matches_found: 0, rag_chunks_found: 0,
  pain_point_used: '', competitor_angle: '', solution_description: '', cited_sources: '', grounded: false } };

// Crawls the lead's homepage + up to 5 relevant same-host subpages. SSRF-guarded.
// NOTE: n8n's Code sandbox has no global URL class, so URLs are parsed with plain string logic.
const src = $json;
const keywords = ['about','service','product','solution','platform','technology','insurance','claim',
  'underwrit','company','team','contact','careers','press','news','industr'];
function stripHtml(html) {
  return html.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ').replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d))).replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
}
// Removes text a subpage shares with the homepage (nav menus, headers, footers) using 6-word shingles.
function removeBoilerplate(text, homeShingles) {
  const w = text.split(' ');
  const keep = w.map(() => true);
  for (let i = 0; i + 6 <= w.length; i++) {
    if (homeShingles.has(w.slice(i, i + 6).join(' ').toLowerCase())) for (let k = i; k < i + 6; k++) keep[k] = false;
  }
  return w.filter((_, i) => keep[i]).join(' ').trim();
}
function parseUrl(s) {
  const m = /^(https?):\/\/([^\/?#:\s]+)(?::(\d{1,5}))?([^?#\s]*)/i.exec((s || '').trim());
  if (!m) return null;
  const protocol = m[1].toLowerCase(), host = m[2].toLowerCase(), port = m[3] || '';
  const path = m[4] || '/';
  return { protocol, host, port, path, origin: `${protocol}://${host}${port ? ':' + port : ''}` };
}
function isSafeHost(h) {
  if (!h || h === 'localhost' || h.endsWith('.localhost') || h.endsWith('.local') || h.endsWith('.internal')) return false;
  if (h.startsWith('[') || !h.includes('.')) return false;
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(h)) {
    const [a, b] = h.split('.').map(Number);
    if (a === 0 || a === 10 || a === 127 || a >= 224 || (a === 169 && b === 254) ||
        (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 100 && b >= 64 && b <= 127)) return false;
  }
  return true;
}
function safeUrl(u) {
  let s = (u == null ? '' : u).toString().trim();
  if (!s) return null;
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s.replace(/^\/+/, '');
  const p = parseUrl(s);
  if (!p || !isSafeHost(p.host)) return null;
  return p.origin + p.path;
}
function resolveLink(href, base) {
  const h = href.trim();
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return base.protocol + ':' + h;
  if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return null;          // mailto:, tel:, javascript:, etc.
  if (h.startsWith('/')) return base.origin + h;
  return base.origin + base.path.replace(/[^\/]*$/, '') + h; // relative path
}

// Clean the Website cell: remove invisible chars, and pull a URL out of text like "Website: www.x.com" or =HYPERLINK("...").
const rawWebsite = (src.website == null ? '' : src.website).toString();
const cleaned = rawWebsite.normalize('NFKC').replace(/[\u0000-\u001f\u007f-\u009f\u00ad\u200b-\u200f\u2028-\u202f\u2060-\u206f\ufeff]/g, '').trim();
const found = cleaned.match(/https?:\/\/[^\s"'<>)]+/i) || cleaned.match(/(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+)+(?:\/[^\s"'<>)]*)?/i);
const candidate = found ? found[0] : '';
const debugBase = { crawler_version: 'v3', website_raw_length: rawWebsite.length, website_cleaned: candidate };
const baseUrl = safeUrl(candidate);
if (!baseUrl) {
  const reason = !rawWebsite.trim() ? 'website field is empty (check the Sheet1 Website column / field mapping)'
    : !candidate ? `no URL found in website value "${cleaned.slice(0, 80)}"`
    : `blocked or unparseable URL "${candidate}"`;
  return { json: { ...src, website_text: `(no usable website: ${reason})`, pages_crawled: [], crawl_ok: false, crawl_debug: { ...debugBase, reason } } };
}
if (!this || !this.helpers || typeof this.helpers.httpRequest !== 'function') {
  return { json: { ...src, website_text: '(crawler cannot make HTTP requests in this n8n setup)', pages_crawled: [], crawl_ok: false,
    crawl_debug: { ...debugBase, reason: 'this.helpers.httpRequest unavailable' } } };
}
const base = parseUrl(baseUrl);

let homepageHtml = '';
try {
  const res = await this.helpers.httpRequest({ method: 'GET', url: baseUrl, timeout: 10000 });
  homepageHtml = typeof res === 'string' ? res : JSON.stringify(res);
} catch (e) {
  return { json: { ...src, website_text: `(homepage unreachable: ${e.message})`, pages_crawled: [], crawl_ok: false, crawl_debug: { ...debugBase, reason: 'homepage request failed: ' + e.message } } };
}
homepageHtml = homepageHtml.slice(0, 2000000);
const homeText = stripHtml(homepageHtml);
const hw = homeText.split(' ');
const homeShingles = new Set();
for (let i = 0; i + 6 <= hw.length; i++) homeShingles.add(hw.slice(i, i + 6).join(' ').toLowerCase());
let combinedText = `[Homepage: ${baseUrl}]\n${homeText.substring(0, 2500)}`;
const pagesCrawled = [baseUrl];

const hrefRegex = /href=["']([^"'#]+)["']/gi;
const rawLinks = new Set(); let match;
while ((match = hrefRegex.exec(homepageHtml)) !== null) rawLinks.add(match[1]);
const sameSite = h => h === base.host || h.replace(/^www\./, '') === base.host.replace(/^www\./, '');
const candidateLinks = [];
for (const href of rawLinks) {
  if (/\.(pdf|jpg|jpeg|png|gif|svg|css|js|zip|ico|webp|mp4|xml)(\?|$)/i.test(href)) continue;
  const full = resolveLink(href, base);
  if (!full) continue;
  const p = parseUrl(full);
  if (!p || !sameSite(p.host) || !isSafeHost(p.host)) continue;
  const clean = p.origin + p.path;
  if (clean.replace(/\/$/, '') === baseUrl.replace(/\/$/, '')) continue;
  if (keywords.some(k => clean.toLowerCase().includes(k))) candidateLinks.push(clean);
}
for (const link of [...new Set(candidateLinks)].slice(0, 5)) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: link, timeout: 8000 });
    const html = (typeof res === 'string' ? res : JSON.stringify(res)).slice(0, 2000000);
    const unique = removeBoilerplate(stripHtml(html), homeShingles);
    if (unique.length < 80) continue; // nothing new on this page
    combinedText += `\n\n---\n[Page: ${link}]\n${unique.substring(0, 1500)}`;
    pagesCrawled.push(link);
  } catch (e) { console.warn(`[CRAWL FAIL] ${link} - ${e.message}`); }
}
return { json: { ...src, website_text: combinedText.substring(0, 8000), pages_crawled: pagesCrawled, crawl_ok: true, crawl_debug: { ...debugBase, reason: 'ok' } } };

