  if (!c.zones) return { zones: null, source: `${c.iso} spans many time zones - fill the Timezone column` };
  return { zones: c.zones, source: c.zones.length > 1 ? `${c.iso} overlap of ${c.zones.length} zones` : 'country' };
}
function isWorkday(localDt, zone) {
  return FRI_SAT_WEEKEND.has(zone) ? (localDt.weekday !== 5 && localDt.weekday !== 6) : localDt.weekday <= 5;
}
function isCallable(dtUtc, zones) {
  return zones.every(z => { const l = dtUtc.setZone(z); return isWorkday(l, z) && l.hour >= CALL_WINDOW.start && l.hour < CALL_WINDOW.end; });
}
// First callable moment >= fromUtc (15-minute steps, handles :30/:45 offsets and DST). ISO UTC string or null.
function nextCallable(fromUtc, zones) {
  let d = fromUtc.toUTC();
  if (isCallable(d, zones)) return d.toISO();
  d = d.set({ minute: Math.floor(d.minute / 15) * 15, second: 0, millisecond: 0 });
  for (let i = 0; i < 4 * 24 * 10; i++) { d = d.plus({ minutes: 15 }); if (isCallable(d, zones)) return d.toISO(); }
  return null;
}
// ---- end shared helpers ----

// Builds the exact call Queue row. This workflow does NOT dial: the Call Dispatcher is the only
// component that places calls, so all gates (DNC, local calling window, retries, concurrency) live there.
const src = $json;
const ph = toE164(src.dm_phone, src.country);
const geo = zonesFor(ph.e164, src.timezone);
let status;
if (!ph.e164) status = 'Invalid Phone - ' + ph.reason;
else if (!src.research_ok || !src.grounded || !(src.solution_description || '').trim()) status = 'Needs Manual Review - insufficient verified content';
else if (!geo.zones) status = 'Needs Manual Review - set Timezone';
else if (!nextCallable(DateTime.utc(), geo.zones)) status = 'Needs Manual Review - no shared calling hours, set Timezone';
else status = 'Ready to Dispatch';
return { json: {
  'Company': src.company || '', 'Website': src.website || '', 'DM Name': src.dm_name || '',
  'DM Title': src.dm_title || '', 'DM Email': src.dm_email || '',
  'Phone Number': ph.e164 || (src.dm_phone || ''),
  'Key Pain Points': (src.pain_points || []).join('; '), 'Competitor Gap': src.competitor_gap || '',
  'Pain Point Used': src.pain_point_used || '', 'Competitor Angle': src.competitor_angle || '',
  'Grounded Solution': src.solution_description || '', 'Cited Sources': src.cited_sources || '',
  'Call Status': status, 'Outcome': '',
  'Call Summary': src.research_error ? ('Research issue: ' + src.research_error) : ('Timezone source: ' + geo.source),
  'Queued At': new Date().toISOString(), 'Next Attempt At': '', 'Retry Count': 0, 'Call ID': '', 'Dispatched At': '',
  'Timezone': geo.zones ? geo.zones.join('|') : ''
}};

// ===== EASY-TO-EDIT CONSTANTS =====
const KB_TOP_K = 3;              // max knowledge rows passed to the pitch agent
const KB_MIN_SCORE = 3;          // minimum relevance score to qualify
const TITLE_WEIGHT = 2;          // per query token found in Title
const BODY_WEIGHT = 1;           // per query token found in Content/Category
const INDUSTRY_BOOST = 3;        // Category matches prospect industry
const PRICING_BOOST = 4;         // Category is pricing and prospect asks about cost
// ==================================

const STOP = new Set(('the and for with you your our are was were this that from into can about what how does have has not but any all its their them they will would could should just also more most very than then there here which who whom when where why using use used via per each other such only own same both few some much many make made like get got over under out off again once do we i me my is it be to of in on at by or as an a synergistic ai solutions solution services service company business').split(' '));
const tokens = s => (s == null ? '' : s).toString().toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter(w => w.length > 2 && !STOP.has(w))
  .map(w => w.length > 5 ? w.replace(/(ations|ation|ings|ing|ions|ion|ies|es|s)$/, '') : w);
const clean = s => (s == null ? '' : s).toString().trim().replace(/[.\s]+$/, '');
const norm = s => (s == null ? '' : s).toString().toLowerCase().replace(/\s+/g, ' ').trim();

const src = $json;

// Eligible rows: only from Read Knowledge Sheet; meaningful Content; Active not no/n/false/0 (blank = active)
let all = [];
try { all = $('Read Knowledge Sheet').all().map(i => i.json); } catch (e) { all = []; }
const rows = all.filter(r => r && (r['Content'] || '').toString().trim()
  && !/^(no|n|false|0)$/i.test((r['Active'] || '').toString().trim()));

// Query: strongest pain point + competitor gap + industry + buying signals
const strongestPain = clean((src.pain_points || [])[0]);
const queryText = [strongestPain, clean(src.competitor_gap), clean(src.industry), clean(src.buying_signals)]
  .filter(Boolean).join('. ').slice(0, 800);
const q = new Set(tokens(queryText));
const industry = (src.industry || '').toString().toLowerCase();
const indTokens = tokens(industry).filter(t => t.length > 3);
const asksPricing = /\b(cost|costs|price|pricing|priced|charge|fee|fees|budget|how much|expensive|rate)\b/i
  .test([strongestPain, src.competitor_gap, src.buying_signals].join(' '));

const scored = rows.map(r => {
  const title = (r['Title'] || '').toString(), cat = (r['Category'] || '').toString(), content = (r['Content'] || '').toString();
  const tT = new Set(tokens(title)), tB = new Set(tokens(content + ' ' + cat));
  let base = 0;
  for (const w of q) { if (tT.has(w)) base += TITLE_WEIGHT; else if (tB.has(w)) base += BODY_WEIGHT; }
  let score = base;
  const c = cat.toLowerCase();
  if (indTokens.some(t => c.includes(t)) ||
      (/insur|p&c|agency|broker/.test(industry) && c.includes('insurance')) ||
      (/health|medical|dental|clinic|hospital|physician|patient|care/.test(industry) && c.includes('health'))) score += INDUSTRY_BOOST;
  if (asksPricing && c.includes('pricing')) score += PRICING_BOOST;
  return { title, cat, content, base, score };
})
// a row must match the query itself; boosts only re-rank, never qualify on their own
.filter(x => x.base > 0 && x.score >= KB_MIN_SCORE)
.sort((a, b) => b.score - a.score);

// De-duplicate identical entries, keep top K
const seen = new Set(); const matched = [];
for (const x of scored) {
  const key = norm(x.title) + '|' + norm(x.content);
  if (seen.has(key)) continue;
  seen.add(key); matched.push(x);
  if (matched.length >= KB_TOP_K) break;
}

const knowledge_context = matched.map((m, i) =>
  `[Knowledge Source ${i + 1}]\nTitle: ${m.title}\nCategory: ${m.cat}\nContent: ${m.content}`).join('\n\n---\n\n');

return { json: { ...src,
  knowledge_context,
  knowledge_sources: matched.map(m => m.title),
  knowledge_matches_found: matched.length,
  rag_chunks_found: matched.length,   // legacy alias so older downstream references keep working
  knowledge_debug: {
    available_rows: rows.length, matched_rows: matched.length, minimum_score: KB_MIN_SCORE,
    matched_titles: matched.map(m => `${m.title} (${m.score})`), query_used: queryText
  } } };

