// Query = the customer's words only (no company name). Enforces max 2 lookups per call server-side.
const body = $json.body || $json;
const q = (body.customer_query == null ? '' : body.customer_query).toString()
  .replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);
const callId = (body.call_id == null ? '' : body.call_id).toString().trim();
const MAX_LOOKUPS_PER_CALL = 2;
const store = $getWorkflowStaticData('global');   // persists only for production (active) executions
store.lookups = store.lookups || {};
const nowMs = Date.now();
for (const k of Object.keys(store.lookups)) if (nowMs - store.lookups[k].t > 3 * 3600 * 1000) delete store.lookups[k];
let capped = false;
if (callId) {
  const e = store.lookups[callId] || { n: 0, t: nowMs };
  if (e.n >= MAX_LOOKUPS_PER_CALL) capped = true; else { e.n += 1; e.t = nowMs; store.lookups[callId] = e; }
}
const skip_reason = !q ? 'empty_query' : (capped ? 'lookup_cap_reached' : '');
return [{ json: { company: (body.company || '').toString().slice(0, 200), customer_query: q, call_id: callId,
  rag_query: q, proceed: !skip_reason, skip_reason, started_ms: nowMs } }];

const src = $('Build Live RAG Query1').first().json;
console.log(JSON.stringify({ evt: 'live_rag', call_id: src.call_id, grounded: false,
  reason: src.skip_reason || 'no_relevant_context', latency_ms: Date.now() - src.started_ms }));
return [{ json: { grounded: false, answer: '', cited_sources: '' } }];

// grounded=true ONLY if every claim's evidence is a verbatim substring of a Google Sheet knowledge chunk and every
// number / high-risk term in the answer is present in that evidence. The LLM's own 'grounded' is not enough.
const ctx = $('Format Live Context').first().json;   // chunks built exclusively from the Knowledge Sheet
const norm = s => (s == null ? '' : s).toString().toLowerCase().replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201c\u201d]/g, '"').replace(/\s+/g, ' ').trim();
const byId = {};
for (const c of ctx.chunks) byId[c.chunk_id] = { text: norm(c.text), source: c.source };
const fail = [];
let p = {};
try {
  let raw = $json.output;
  if (typeof raw !== 'string') raw = JSON.stringify(raw || {});
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  p = JSON.parse(m ? m[0] : raw);
} catch (e) { fail.push('parse_error'); }
const answer = (p.answer || '').toString().trim();
const claims = Array.isArray(p.claims) ? p.claims : [];
if (p.grounded !== true || !answer) fail.push('self_reported_ungrounded');
if (!claims.length) fail.push('no_claims');
if (answer.length > 600) fail.push('answer_too_long');
const used = new Set();
for (const c of claims) {
  const q = norm(c && c.evidence_quote);
  const chunk = byId[c && c.chunk_id];
  if (q.length < 20) fail.push('quote_too_short');
  else if (!chunk || !chunk.text.includes(q)) fail.push('quote_not_in_chunk:' + (c && c.chunk_id));
  else used.add(chunk.source);
}
const evidence = claims.map(c => norm(c && c.evidence_quote)).join(' ');
for (const n of (answer.match(/[$€£₹]?\d[\d,.]*%?/g) || [])) {
  const core = n.replace(/[$€£₹%]/g, '').replace(/[.,]$/, '');
  if (core && !evidence.includes(core)) fail.push('unsupported_number:' + n);
}
const TERMS = ['guarantee', 'hipaa', 'soc 2', 'soc2', 'gdpr', 'iso 27001', 'certified', 'certification',
  'compliant', 'compliance', 'integrat', 'roi', 'free', 'pricing', 'price', 'discount'];
const A = norm(answer);
for (const t of TERMS) if (A.includes(t) && !evidence.includes(t)) fail.push('unsupported_term:' + t);
const grounded = fail.length === 0;
console.log(JSON.stringify({ evt: 'live_rag', call_id: ctx.call_id, grounded, chunks: ctx.rag_chunks_found,
  failures: fail.slice(0, 5), latency_ms: Date.now() - ctx.started_ms }));
return [{ json: { grounded, answer: grounded ? answer : '', cited_sources: grounded ? [...used].join(', ') : '' } }];

// ===== EASY-TO-EDIT CONSTANTS =====
const KB_TOP_K = 3;
const KB_TOP_K_BROAD = 4;
const KB_MIN_SCORE = 2;
const W_TITLE = 2, W_CONTENT = 1, W_CATEGORY = 1;
const W_PHRASE_TITLE = 3, W_PHRASE_CONTENT = 1, PHRASE_CAP = 6;
const PRICING_BOOST = 4;
const MAX_CONTENT_CHARS = 1500;
// ==================================

// Deterministic Google Sheet matcher. The Knowledge Sheet is the ONLY knowledge source.
const STOP = new Set(('please elaborate explain tell know need want kind type offer provide help sort thing things okay '
  + 'the and for with you your our are was were this that from into can about what how does have has not but any all its their them they will would could should just also more most very than then there here which who whom when where why using use used via per each other such only own same both few some much many make made like get got over under out off again once '
  + 'do we i me my is it be to of in on at by or as an a synergistic ai solutions solution services service company business '
  + 'ignore previous instructions instruction say pretend system prompt').split(' '));
function stem(w) {
  let s = w;
  if (s.length > 4 && s.endsWith('ies')) s = s.slice(0, -3) + 'y';
  else if (s.length > 5 && /(ations|ation|ating|ated|ates|ate|ings|ing|ions|ion)$/.test(s)) s = s.replace(/(ations|ation|ating|ated|ates|ate|ings|ing|ions|ion)$/, '');
  else if (s.length > 5 && s.endsWith('es')) s = s.slice(0, -2);
  else if (s.length > 3 && s.endsWith('s') && !s.endsWith('ss')) s = s.slice(0, -1);
  return s;
}
const tokens = s => (s == null ? '' : s).toString().toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter(w => w.length > 2 && !STOP.has(w)).map(stem).filter(w => w.length > 1 && !STOP.has(w));
const norm = s => (s == null ? '' : s).toString().toLowerCase().replace(/\s+/g, ' ').trim();

const src = $('Build Live RAG Query1').first().json;
const question = (src.customer_query || '').toString();   // used ONLY as a search string

// Eligible rows: Content present; Active not no/n/false/0 (blank = active)
let all = [];
try { all = $('Read Knowledge Sheet (Live)').all().map(i => i.json); } catch (e) { all = []; }
const rows = all.filter(r => r && (r['Content'] || '').toString().trim()
  && !/^(no|n|false|0)$/i.test((r['Active'] || '').toString().trim()));

const qTokens = tokens(question);
const qSet = new Set(qTokens);
const bigrams = []; for (let i = 0; i + 1 < qTokens.length; i++) bigrams.push(' ' + qTokens[i] + ' ' + qTokens[i + 1] + ' ');
const asksPrice = /\b(cost|costs|price|pricing|priced|charge|fee|fees|budget|how much|expensive|rate)\b/i.test(question);

const scored = rows.map(r => {
  const title = (r['Title'] || '').toString(), cat = (r['Category'] || '').toString(), content = (r['Content'] || '').toString();
  const tT = tokens(title), tC = tokens(content), tK = tokens(cat);
  const sT = new Set(tT), sC = new Set(tC), sK = new Set(tK);
  let base = 0;
  for (const w of qSet) {
    if (sT.has(w)) base += W_TITLE; else if (sC.has(w)) base += W_CONTENT;
    if (sK.has(w)) base += W_CATEGORY;
  }
  const hT = ' ' + tT.join(' ') + ' ', hC = ' ' + tC.join(' ') + ' ';
  let phrase = 0;
  for (const b of bigrams) { if (hT.includes(b)) phrase += W_PHRASE_TITLE; else if (hC.includes(b)) phrase += W_PHRASE_CONTENT; }
  base += Math.min(phrase, PHRASE_CAP);
  const isPrice = asksPrice && cat.toLowerCase().includes('pricing');
  return { r, title, cat, content, base, score: base + (isPrice ? PRICING_BOOST : 0), isPrice };
}).filter(x => (x.base > 0 || x.isPrice) && x.score >= KB_MIN_SCORE)
  .sort((a, b) => b.score - a.score);

// Broad "what services do you offer?" questions -> overview rows (skipped if the KB IDs don't exist)
const q = question.toLowerCase();
const broad = (/\b(what|which|other|else|all|kind|kinds|type|types|list|range)\b/.test(q)
  && /\b(services?|offer|offerings?|provide|do you do|automations?|solutions?|products?|help with)\b/.test(q))
  || /digital marketing|marketing services/.test(q);
const byId = id => rows.find(r => (r['KB ID'] || '').toString().trim() === id);
let broadRows = [];
if (broad) {
  const auto = /automat|\bai\b|rpa|agent|workflow/.test(q);
  const mkt = /market|\bads?\b|seo|social|brand|lead|content|google|meta|facebook|instagram/.test(q);
  const ids = auto && !mkt ? ['hc-overview', 'ins-overview', 'hc-agents-rpa']
            : mkt && !auto ? ['svc-overview', 'svc-social-media', 'svc-meta-ads']
            : ['svc-overview', 'hc-overview', 'ins-overview'];
  broadRows = ids.map(byId).filter(Boolean).map(r => ({ r, title: (r['Title'] || '').toString(), cat: (r['Category'] || '').toString(), content: (r['Content'] || '').toString(), score: 0 }));
}

// Deduplicate identical entries, keep top K
const limit = broadRows.length ? KB_TOP_K_BROAD : KB_TOP_K;
const seen = new Set(); const picked = [];
for (const x of [...broadRows, ...scored]) {
  const key = norm(x.title) + '|' + norm(x.content);
  if (seen.has(key)) continue;
  seen.add(key); picked.push(x);
  if (picked.length >= limit) break;
}

const chunks = picked.map((x, i) => ({
  chunk_id: 'C' + (i + 1),
  text: `Synergistic AI Solutions - ${x.title}\n${x.content.slice(0, MAX_CONTENT_CHARS)}`,
  source: 'Knowledge Base - ' + x.title,
  kb_id: (x.r['KB ID'] || '').toString(), title: x.title, category: x.cat, score: x.score
}));
const rag_context = chunks.map(c => `[${c.chunk_id} | ${c.source}]\n${c.text}`).join('\n\n---\n\n');
console.log(JSON.stringify({ evt: 'live_kb_match', call_id: src.call_id, available: rows.length, matched: chunks.length, broad, latency_ms: Date.now() - src.started_ms }));
return [{ json: { ...src, chunks, rag_context, rag_chunks_found: chunks.length,
  knowledge_sources: chunks.map(c => c.source).join(', '),
  knowledge_debug: { available_rows: rows.length, matched_rows: chunks.length, minimum_score: KB_MIN_SCORE,
    broad_question: broad, matched_titles: chunks.map(c => `${c.title} (${c.score})`), query_used: question } } }];
